function onSuccess() {
    naxToast({
        title: '保存成功',
        type: 'success'
    } as UTSJSONObject)
}

function onError() {
    naxToast({
        title: '提交失败',
        type: 'error'
    } as UTSJSONObject)
}

function onWarning() {
    naxToast({
        title: '请注意风险',
        type: 'warning'
    } as UTSJSONObject)
}

function onInfo() {
    naxToast({
        title: '已为你更新内容',
        type: 'info'
    } as UTSJSONObject)
}

function onPos(pos : string) {
    naxToast({
        title: '位置：' + pos,
        type: 'text',
        position: pos
    } as UTSJSONObject)
}

function onLoading() {
    naxToastLoading('提交中…', true)
    // loading 默认 duration=0 且带遮罩，需手动关闭或稍后再调 hide
    setTimeout(() => {
        hideNaxToast()
        naxToastSuccess('提交完成')
    }, 2500)
}

function onHide() {
    hideNaxToast()
}

function onCustomIcon() {
    naxToast({
        title: '收藏成功',
        type: 'text',
        icon: 'star',
        showIcon: true
    } as UTSJSONObject)
}

function onLong() {
    naxToast({
        title: '这条会停留 4 秒',
        type: 'info',
        duration: 4000
    } as UTSJSONObject)
}

// 鸿蒙/App 请优先 hex（如 #18a058）；rgba 在端上可能失效
function onCustomBg(color : string) {
    naxToast({
        title: '自定义背景色',
        type: 'text',
        bg: color,
        color: '#ffffff',
        showIcon: false
    } as UTSJSONObject)
}

function onQuickSuccess() {
    naxToastSuccess('快捷成功')
}

function onQuickError() {
    naxToastError('快捷错误')
}

// 同系列：naxToastWarning('注意') / naxToastInfo('提示') / naxToastLoading('加载中', true)
